[package]
name = "swarm-cli"
version.workspace = true
edition.workspace = true

[dependencies]
swarm-core = { path = "../swarm-core" }
clap = { workspace = true }
uuid = { workspace = true }
serde_json = { workspace = true }

//! CLI: seed / status / review / reopen / unblock.

use clap::{Parser, Subcommand};
use swarm_core::{Budget, Needs, SwarmDispatcher, TaskContract, Verdict};
use uuid::Uuid;

#[derive(Parser)]
#[command(name = "swarm-cli", version, about = "Swarm Dispatcher CLI")]
struct Cli {
    #[command(subcommand)]
    command: Cmd,
}

#[derive(Subcommand)]
enum Cmd {
    /// Создать демо-граф: корень + 2 зависимые задачи.
    Seed,
    /// Показать все задачи.
    Status,
    /// Оставить ревью.
    Review {
        task_id: Uuid,
        artifact_ref: String,
        #[arg(value_parser = ["approve", "changes", "reject"])]
        verdict: String,
    },
    /// Переоткрыть завершённую задачу (каскадный откат).
    Reopen { task_id: Uuid, actor: String },
    /// Разблокировать задачу.
    Unblock { task_id: Uuid, actor: String },
}

fn main() {
    let dsn = std::env::var("DATABASE_URL").expect("DATABASE_URL required");
    let cli = Cli::parse();
    let mut d = SwarmDispatcher::connect(&dsn).expect("connect to Postgres");

    match cli.command {
        Cmd::Seed => seed(&mut d),
        Cmd::Status => status(&mut d),
        Cmd::Review { task_id, artifact_ref, verdict } => {
            let v = match verdict.as_str() {
                "approve" => Verdict::Approved,
                "changes" => Verdict::ChangesRequested,
                _ => Verdict::Rejected,
            };
            let checks = serde_json::json!([
                {"type": "cmd", "status": "pass", "exit_code": 0}
            ]);
            match d.submit_review(task_id, &artifact_ref, "cli-reviewer", v, &checks) {
                Ok(state) => println!("new state: {state}"),
                Err(e) => eprintln!("error: {e}"),
            }
        }
        Cmd::Reopen { task_id, actor } => {
            match d.reopen(task_id, &actor) {
                Ok(n) => println!("blocked {n} descendants"),
                Err(e) => eprintln!("error: {e}"),
            }
        }
        Cmd::Unblock { task_id, actor } => {
            match d.unblock(task_id, &actor) {
                Ok(state) => println!("new state: {state}"),
                Err(e) => eprintln!("error: {e}"),
            }
        }
    }
}

fn contract(kind: &str) -> TaskContract {
    TaskContract {
        kind: kind.to_string(),
        description: None,
        checks: vec![serde_json::json!({"type": "cmd", "run": "true"})],
        needs: Needs::default(),
        budget: Budget::default(),
    }
}

fn seed(d: &mut SwarmDispatcher) {
    let root = Uuid::new_v4();
    d.add_task(root, &contract("root"), None, 10_000, 10)
        .expect("add root");

    for i in 1..=2 {
        let child = Uuid::new_v4();
        d.add_task(child, &contract(&format!("child-{i}")), Some(root), 10_000, 5)
            .expect("add child");
        d.add_dep(child, root).expect("add dep");
        println!("created child {} depends on root {}", child, root);
    }
    println!("seed done, root = {root}");
}

fn status(d: &mut SwarmDispatcher) {
    // Чтение через task_status(): прямой SELECT к tasks сервисным ролям закрыт
    // после roles.sql.
    let tasks = match d.list_task_status(200) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("error: {e}");
            return;
        }
    };

    if tasks.is_empty() {
        println!("(no tasks)");
        return;
    }

    println!(
        "{:<38} {:<10} {:<8} {:<10} {:>4} {:>4}",
        "id", "state", "epoch", "owner", "att", "rw"
    );
    for t in tasks {
        println!(
            "{:<38} {:<10} {:<8} {:<10} {:>4} {:>4}",
            t.id,
            t.state,
            t.lease_epoch,
            t.owner.as_deref().unwrap_or("-"),
            t.attempts,
            t.rework,
        );
        if let Some(reason) = t.block_reason {
            println!("    blocked: {reason}");
        }
    }
}

[package]
name = "swarm-core"
version.workspace = true
edition.workspace = true

[dependencies]
postgres = { workspace = true }
thiserror = { workspace = true }
uuid = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }

[dev-dependencies]

[[test]]
name = "integration_alt"
path = "tests/alt/integration_alt.rs"

use crate::errors::DispatcherError;
use crate::types::{Lease, TaskContract, TaskRow, TaskStatusRow, Verdict};
use postgres::{Client, NoTls};
use uuid::Uuid;

pub struct SwarmDispatcher {
    client: Client,
}

impl SwarmDispatcher {
    /// Единственный `?`-совместимый путь к `postgres::Error` — явный `map_err`.
    /// Никогда не полагаться на `From<postgres::Error>` (см. комментарий в `errors.rs`).
    pub fn connect(dsn: &str) -> Result<Self, DispatcherError> {
        let client = Client::connect(dsn, NoTls).map_err(DispatcherError::from_pg)?;
        Ok(Self { client })
    }

    // ---------- чтение ----------

    /// Список задач **напрямую из таблицы** — доступно только суперпользователю
    /// (тесты). Сервисные роли читают через [`SwarmDispatcher::list_task_status`].
    pub fn list_tasks(
        &mut self,
        filter_state: Option<&str>,
        limit: i64,
    ) -> Result<Vec<TaskRow>, DispatcherError> {
        let rows = match filter_state {
            Some(state) => self
                .client
                .query(
                    "SELECT id, root_id, state, lease_owner, lease_epoch, \
                            attempts, rework, priority, block_reason \
                     FROM tasks WHERE state = $1 \
                     ORDER BY priority DESC, created_at ASC LIMIT $2",
                    &[&state, &limit],
                )
                .map_err(DispatcherError::from_pg)?,
            None => self
                .client
                .query(
                    "SELECT id, root_id, state, lease_owner, lease_epoch, \
                            attempts, rework, priority, block_reason \
                     FROM tasks \
                     ORDER BY priority DESC, created_at ASC LIMIT $1",
                    &[&limit],
                )
                .map_err(DispatcherError::from_pg)?,
        };

        Ok(rows
            .iter()
            .map(|r| TaskRow {
                id: r.get(0),
                root_id: r.get(1),
                state: r.get(2),
                owner: r.get(3),
                lease_epoch: r.get(4),
                attempts: r.get(5),
                rework: r.get(6),
                priority: r.get(7),
                block_reason: r.get(8),
            })
            .collect())
    }

    /// Список задач через `task_status(n)` — путь чтения для сервисных ролей.
    /// Прямой SELECT к `tasks` после `roles.sql` им закрыт.
    pub fn list_task_status(&mut self, limit: i32) -> Result<Vec<TaskStatusRow>, DispatcherError> {
        let rows = self
            .client
            .query(
                "SELECT id, root_id, state, lease_epoch, lease_owner, \
                        attempts, rework, block_reason \
                 FROM task_status($1)",
                &[&limit],
            )
            .map_err(DispatcherError::from_pg)?;

        Ok(rows
            .iter()
            .map(|r| TaskStatusRow {
                id: r.get(0),
                root_id: r.get(1),
                state: r.get(2),
                lease_epoch: r.get(3),
                owner: r.get(4),
                attempts: r.get(5),
                rework: r.get(6),
                block_reason: r.get(7),
            })
            .collect())
    }

    // ---------- граф ----------

    pub fn add_task(
        &mut self,
        task_id: Uuid,
        contract: &TaskContract,
        root_id: Option<Uuid>,
        budget_cap: i64,
        priority: i32,
    ) -> Result<(), DispatcherError> {
        contract.validate()?;
        let body = serde_json::to_value(contract)?;
        self.client
            .execute(
                "SELECT add_task($1, $2, $3::jsonb, $4, $5)",
                &[&task_id, &root_id, &body, &budget_cap, &priority],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    pub fn add_dep(&mut self, task_id: Uuid, dep_id: Uuid) -> Result<(), DispatcherError> {
        self.client
            .execute("SELECT add_dep($1, $2)", &[&task_id, &dep_id])
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    pub fn promote_ready(&mut self) -> Result<i32, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT promote_ready()", &[])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- воркеры ----------

    pub fn register_worker(
        &mut self,
        worker_id: &str,
        capabilities: &serde_json::Value,
        tags: &[String],
    ) -> Result<(), DispatcherError> {
        self.client
            .execute(
                "SELECT register_worker($1, $2::jsonb, $3)",
                &[&worker_id, capabilities, &tags],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    /// Выдаёт аренду. Контракт возвращается **сырым JSON** — разбор только через
    /// [`Lease::typed_contract`]. См. комментарий к `Lease` в `types.rs`.
    pub fn claim(
        &mut self,
        worker_id: &str,
        lease_sec: i32,
    ) -> Result<Option<Lease>, DispatcherError> {
        let rows = self
            .client
            .query(
                "SELECT out_task_id, out_contract, out_epoch, out_budget, out_spent \
                 FROM claim_task($1, $2)",
                &[&worker_id, &lease_sec],
            )
            .map_err(DispatcherError::from_pg)?;
        if rows.is_empty() {
            return Ok(None);
        }
        let r = &rows[0];
        Ok(Some(Lease {
            task_id: r.get(0),
            contract: r.get(1), // сырой JSON: никакого from_value здесь
            epoch: r.get(2),
            budget_cap: r.get(3),
            spent_tokens: r.get(4),
            worker_id: worker_id.to_owned(),
        }))
    }

    /// Не бросает исключение при потере аренды — возвращает `Ok(false)`.
    /// Так воркер может реагировать на потерю без `catch`.
    pub fn heartbeat(&mut self, lease: &Lease, extend_sec: i32) -> Result<bool, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT heartbeat($1, $2, $3, $4)",
                &[&lease.task_id, &lease.worker_id, &lease.epoch, &extend_sec],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    pub fn save_artifact(
        &mut self,
        lease: &Lease,
        artifact_ref: &str,
        storage_path: &str,
        content_type: Option<&str>,
        size_bytes: Option<i64>,
    ) -> Result<(), DispatcherError> {
        self.client
            .execute(
                "SELECT save_artifact($1, $2, $3, $4, $5, $6, $7)",
                &[
                    &lease.task_id,
                    &lease.worker_id,
                    &lease.epoch,
                    &artifact_ref,
                    &storage_path,
                    &content_type,
                    &size_bytes,
                ],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    /// Возвращает новое состояние задачи: `"review"` или `"blocked"`.
    pub fn complete(
        &mut self,
        lease: &Lease,
        result_ref: &str,
        tokens: i64,
    ) -> Result<String, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT complete_task($1, $2, $3, $4, $5)",
                &[&lease.task_id, &lease.worker_id, &lease.epoch, &result_ref, &tokens],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- ревью ----------

    /// Возвращает новое состояние задачи: `"done"`, `"ready"` или `"blocked"`.
    pub fn submit_review(
        &mut self,
        task_id: Uuid,
        artifact_ref: &str,
        reviewer: &str,
        verdict: Verdict,
        checks: &serde_json::Value,
    ) -> Result<String, DispatcherError> {
        let row = self
            .client
            .query_one(
                "SELECT submit_review($1, $2, $3, $4, $5::jsonb)",
                &[&task_id, &artifact_ref, &reviewer, &verdict.as_str(), checks],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- сторож ----------

    pub fn reclaim_expired(&mut self) -> Result<i32, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT reclaim_expired()", &[])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    // ---------- операторские ----------

    pub fn reopen(&mut self, task_id: Uuid, actor: &str) -> Result<i32, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT reopen_task($1, $2)", &[&task_id, &actor])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    pub fn unblock(&mut self, task_id: Uuid, actor: &str) -> Result<String, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT unblock_task($1, $2)", &[&task_id, &actor])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }

    pub fn verify_chain(&mut self, task_id: Uuid) -> Result<bool, DispatcherError> {
        let row = self
            .client
            .query_one("SELECT verify_chain($1)", &[&task_id])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }
}

// ---------- транзакции ----------
// Два лайфтайма обязательны: `&'a mut Transaction<'a>` делает заём бесконечным
// (инвариантность), и `tx.commit()` после замыкания не компилируется (E0597/E0505).
pub struct DispatcherTx<'a, 'b> {
    tx: &'a mut postgres::Transaction<'b>,
}

impl SwarmDispatcher {
    /// Всё или ничего: `Err` из замыкания (или паника) = rollback, `Ok` = commit.
    pub fn with_transaction<F, T>(&mut self, f: F) -> Result<T, DispatcherError>
    where
        F: FnOnce(&mut DispatcherTx<'_, '_>) -> Result<T, DispatcherError>,
    {
        let mut tx = self.client.transaction().map_err(DispatcherError::from_pg)?;
        let out = {
            let mut w = DispatcherTx { tx: &mut tx };
            f(&mut w)? // при Err tx дропается без commit -> rollback
        };
        tx.commit().map_err(DispatcherError::from_pg)?;
        Ok(out)
    }
}

impl DispatcherTx<'_, '_> {
    pub fn add_task(
        &mut self,
        task_id: Uuid,
        contract: &TaskContract,
        root_id: Option<Uuid>,
        budget_cap: i64,
        priority: i32,
    ) -> Result<(), DispatcherError> {
        contract.validate()?;
        let body = serde_json::to_value(contract)?;
        self.tx
            .execute(
                "SELECT add_task($1, $2, $3::jsonb, $4, $5)",
                &[&task_id, &root_id, &body, &budget_cap, &priority],
            )
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    pub fn add_dep(&mut self, task_id: Uuid, dep_id: Uuid) -> Result<(), DispatcherError> {
        self.tx
            .execute("SELECT add_dep($1, $2)", &[&task_id, &dep_id])
            .map_err(DispatcherError::from_pg)?;
        Ok(())
    }

    pub fn promote_ready(&mut self) -> Result<i32, DispatcherError> {
        let row = self
            .tx
            .query_one("SELECT promote_ready()", &[])
            .map_err(DispatcherError::from_pg)?;
        Ok(row.get(0))
    }
}

//! ПРАВИЛО: `postgres::Error` НЕ конвертируется через `?`/`#[from]`.
//!
//! У варианта `Database` стоит `#[source]`, а не `#[from]`. Иначе любой
//! будущий `?` на `postgres::Error` молча превратит доменную ошибку
//! (`LeaseLost`, `CycleDetected`, …) в общий `Database`, и маппинг SQLSTATE
//! будет обойдён. Любой `?` на ошибке postgres обязан идти явно:
//!
//! ```ignore
//! self.client.query_one(...).map_err(DispatcherError::from_pg)?;
//! Client::connect(dsn, NoTls).map_err(DispatcherError::from_pg)?;
//! ```

use thiserror::Error;

/// Полная иерархия ошибок диспетчера.
///
/// Соответствие SQLSTATE → вариант зафиксировано в `from_sqlstate`.
/// Добавление нового SQLSTATE требует добавления варианта и теста.
#[derive(Debug, Error)]
pub enum DispatcherError {
    #[error("lease lost or expired")]
    LeaseLost,

    #[error("artifact not found")]
    ArtifactMissing,

    #[error("contract invalid")]
    ContractInvalid,

    #[error("task not found")]
    TaskNotFound,

    #[error("dependency cycle")]
    CycleDetected,

    #[error("depth limit exceeded")]
    DepthExceeded,

    #[error("fanout limit exceeded")]
    FanoutExceeded,

    #[error("task limit exceeded")]
    TaskLimitExceeded,

    #[error("task is not in 'done' state")]
    NotDone,

    #[error("root task not found")]
    RootNotFound,

    #[error("dependency spans different roots")]
    CrossRootDependency,

    #[error("task is not in 'pending' state")]
    TaskNotPending,

    #[error("task is not in 'blocked' state")]
    NotBlocked,

    #[error("review is stale (wrong artifact or state)")]
    ReviewStale,

    #[error("self-review is not allowed")]
    SelfReview,

    #[error("acceptance checks failed")]
    ChecksFailed,

    #[error("worker capabilities are invalid")]
    WorkerInvalid,

    #[error("worker is not registered")]
    WorkerUnknown,

    #[error("database error")]
    Database(#[source] postgres::Error),

    #[error("serialization error")]
    Serialization(#[from] serde_json::Error),
}

impl DispatcherError {
    /// Маппинг ошибки `postgres` в доменную ошибку по SQLSTATE.
    ///
    /// Если SQLSTATE неизвестен — возвращаем как есть.
    pub fn from_pg(e: postgres::Error) -> Self {
        if let Some(db) = e.as_db_error() {
            if let Some(known) = Self::from_sqlstate(db.code().code()) {
                return known;
            }
        }
        Self::Database(e)
    }

    fn from_sqlstate(code: &str) -> Option<Self> {
        Some(match code {
            "LS001" => Self::LeaseLost,
            "AR001" => Self::ArtifactMissing,
            "CT001" => Self::ContractInvalid,
            "GR000" => Self::TaskNotFound,
            "GR001" => Self::CycleDetected,
            "GR002" => Self::DepthExceeded,
            "GR003" => Self::FanoutExceeded,
            "GR004" => Self::TaskLimitExceeded,
            "GR005" => Self::NotDone,
            "GR006" => Self::RootNotFound,
            "GR007" => Self::CrossRootDependency,
            "GR008" => Self::TaskNotPending,
            "GR009" => Self::NotBlocked,
            "RV001" => Self::ReviewStale,
            "RV002" => Self::SelfReview,
            "RV003" => Self::ChecksFailed,
            "WK001" => Self::WorkerInvalid,
            "WK002" => Self::WorkerUnknown,
            _ => return None,
        })
    }

    pub fn is_transient(&self) -> bool {
        // Сериализация/дедлоки Postgres. В v0 ретраев нет — заготовка.
        matches!(self, Self::Database(e)
            if matches!(e.code().map(|c| c.code()), Some("40001" | "40P01")))
    }

    /// `insufficient_privilege` (42501): роли не хватает гранта на функцию/таблицу.
    ///
    /// Нужно вызывающему, который хочет отличить «нет прав читать» от
    /// «нет данных» — например, Planner под ролью `swarm_planner` без гранта
    /// на `task_status`.
    pub fn is_insufficient_privilege(&self) -> bool {
        matches!(self, Self::Database(e)
            if e.code().map(|c| c.code() == "42501").unwrap_or(false))
    }

    /// `unique_violation` (23505): вставка конфликтует с существующей строкой.
    ///
    /// Для Planner это сигнал идемпотентного пропуска: граф с таким `root_id`
    /// уже создан (актуально, когда читать `task_status` роли не разрешено).
    pub fn is_unique_violation(&self) -> bool {
        matches!(self, Self::Database(e)
            if e.code().map(|c| c.code() == "23505").unwrap_or(false))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sqlstate_known_codes_map() {
        // Проверяем именно маппинг SQLSTATE → вариант, а не текст сообщения.
        use DispatcherError::*;
        let cases: [(&str, fn(&DispatcherError) -> bool); 18] = [
            ("LS001", |e| matches!(e, LeaseLost)),
            ("AR001", |e| matches!(e, ArtifactMissing)),
            ("CT001", |e| matches!(e, ContractInvalid)),
            ("GR000", |e| matches!(e, TaskNotFound)),
            ("GR001", |e| matches!(e, CycleDetected)),
            ("GR002", |e| matches!(e, DepthExceeded)),
            ("GR003", |e| matches!(e, FanoutExceeded)),
            ("GR004", |e| matches!(e, TaskLimitExceeded)),
            ("GR005", |e| matches!(e, NotDone)),
            ("GR006", |e| matches!(e, RootNotFound)),
            ("GR007", |e| matches!(e, CrossRootDependency)),
            ("GR008", |e| matches!(e, TaskNotPending)),
            ("GR009", |e| matches!(e, NotBlocked)),
            ("RV001", |e| matches!(e, ReviewStale)),
            ("RV002", |e| matches!(e, SelfReview)),
            ("RV003", |e| matches!(e, ChecksFailed)),
            ("WK001", |e| matches!(e, WorkerInvalid)),
            ("WK002", |e| matches!(e, WorkerUnknown)),
        ];
        for (code, is_expected) in cases {
            let e = DispatcherError::from_sqlstate(code)
                .unwrap_or_else(|| panic!("sqlstate {code} not mapped"));
            assert!(is_expected(&e), "sqlstate {code} mapped to wrong variant: {e:?}");
        }
    }

    #[test]
    fn sqlstate_unknown_returns_none() {
        assert!(DispatcherError::from_sqlstate("99999").is_none());
        assert!(DispatcherError::from_sqlstate("").is_none());
        assert!(DispatcherError::from_sqlstate("XX000").is_none());
    }
}

pub mod dispatcher;
pub mod errors;
pub mod types;

pub use dispatcher::{DispatcherTx, SwarmDispatcher};
pub use errors::DispatcherError;
pub use types::{
    Budget, Lease, Needs, TaskContract, TaskRow, TaskState, TaskStatusRow, Verdict,
};

use crate::errors::DispatcherError;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Needs {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub min_ram_gb: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub coder_class: Option<f64>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub affinity_tags: Vec<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Budget {
    #[serde(default = "default_attempts")]
    pub attempts: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_rework: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_depth: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_children: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_tasks: Option<u32>,
}

fn default_attempts() -> u32 { 3 }

impl Default for Budget {
    fn default() -> Self {
        Self {
            attempts: default_attempts(),
            max_rework: None,
            max_depth: None,
            max_children: None,
            max_tasks: None,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TaskContract {
    pub kind: String,
    /// Текст задачи от пользователя (через Planner). Пробрасывается воркеру,
    /// чтобы LLM знал, что именно делать. Помечается как недоверенный ввод
    /// в промпте воркера (`<untrusted>`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
    /// Непустой массив check-ов. Интерпретируется воркером, схема проверяет только форму.
    pub checks: Vec<serde_json::Value>,
    #[serde(default)]
    pub needs: Needs,
    #[serde(default)]
    pub budget: Budget,
}

impl TaskContract {
    /// Локальная валидация формы. Совпадает по строгости с SQL-валидацией:
    /// что отклоняем здесь — отклонил бы и SQL. SQL остаётся источником истины.
    pub fn validate(&self) -> Result<(), DispatcherError> {
        if self.checks.is_empty() {
            return Err(DispatcherError::ContractInvalid);
        }
        Ok(())
    }
}

/// Аренда, возвращённая из `claim_task`. Frozen-семантика на стороне вызывающего.
///
/// `contract` хранится как **сырой JSON**, а не как `TaskContract`: SQL
/// принимает контракты, которые Rust-тип не разберёт (без `kind`, с дробным
/// `budget.attempts`). Если бы `claim` десериализовал контракт сразу после
/// выдачи аренды, задача зависла бы в `leased` на весь срок аренды, затем
/// `reclaim_expired` сжёг бы попытку, и через `attempts` попыток задача ушла
/// бы в `blocked`. Разбор — только явно, через [`Lease::typed_contract`].
#[derive(Debug, Clone)]
pub struct Lease {
    pub task_id: Uuid,
    pub contract: serde_json::Value,
    pub epoch: i64,
    pub budget_cap: i64,
    pub spent_tokens: i64,
    pub worker_id: String,
}

impl Lease {
    /// Типизированный разбор контракта. **Не влияет на аренду** — вызывается
    /// только тем, кому нужен типизированный доступ к полям контракта.
    pub fn typed_contract(&self) -> Result<TaskContract, DispatcherError> {
        serde_json::from_value(self.contract.clone()).map_err(Into::into)
    }
}

/// Вердикт ревьюера.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verdict {
    Approved,
    ChangesRequested,
    Rejected,
}

impl Verdict {
    pub fn as_str(&self) -> &'static str {
        match self {
            Verdict::Approved => "approved",
            Verdict::ChangesRequested => "changes_requested",
            Verdict::Rejected => "rejected",
        }
    }
}

/// Состояния задачи. Соответствует CHECK в схеме.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaskState {
    Pending,
    Ready,
    Leased,
    Review,
    Done,
    Blocked,
}

impl TaskState {
    pub fn as_str(&self) -> &'static str {
        match self {
            TaskState::Pending => "pending",
            TaskState::Ready => "ready",
            TaskState::Leased => "leased",
            TaskState::Review => "review",
            TaskState::Done => "done",
            TaskState::Blocked => "blocked",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        Some(match s {
            "pending" => TaskState::Pending,
            "ready" => TaskState::Ready,
            "leased" => TaskState::Leased,
            "review" => TaskState::Review,
            "done" => TaskState::Done,
            "blocked" => TaskState::Blocked,
            _ => return None,
        })
    }
}

/// Строка функции `task_status()` — путь чтения, доступный сервисным ролям
/// после применения `roles.sql` (прямой SELECT к `tasks` им закрыт).
#[derive(Debug, Clone)]
pub struct TaskStatusRow {
    pub id: Uuid,
    pub root_id: Uuid,
    pub state: String,
    pub lease_epoch: i64,
    pub owner: Option<String>,
    pub attempts: i32,
    pub rework: i32,
    pub block_reason: Option<String>,
}

/// Строка таблицы `tasks` для отображения в CLI / отчётах.
#[derive(Debug, Clone)]
pub struct TaskRow {
    pub id: Uuid,
    pub root_id: Uuid,
    pub state: String,
    pub owner: Option<String>,
    pub lease_epoch: i64,
    pub attempts: i32,
    pub rework: i32,
    pub priority: i32,
    pub block_reason: Option<String>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn contract_valid() {
        let c = TaskContract {
            kind: "test".into(),
            description: None,
            checks: vec![serde_json::json!({"type": "cmd", "run": "true"})],
            needs: Needs::default(),
            budget: Budget::default(),
        };
        assert!(c.validate().is_ok());
    }

    #[test]
    fn contract_empty_checks_rejected() {
        let c = TaskContract {
            kind: "test".into(),
            description: None,
            checks: vec![],
            needs: Needs::default(),
            budget: Budget::default(),
        };
        assert!(matches!(
            c.validate(),
            Err(DispatcherError::ContractInvalid)
        ));
    }

    #[test]
    fn contract_deserialize_minimal() {
        let raw = r#"{"kind":"x","checks":[{"type":"cmd"}]}"#;
        let c: TaskContract = serde_json::from_str(raw).unwrap();
        assert_eq!(c.kind, "x");
        assert_eq!(c.checks.len(), 1);
        assert_eq!(c.budget.attempts, 3);
        assert!(c.needs.min_ram_gb.is_none());
        assert!(c.needs.affinity_tags.is_empty());
    }

    #[test]
    fn contract_serialize_omits_none() {
        let c = TaskContract {
            kind: "x".into(),
            description: None,
            checks: vec![serde_json::json!({"type": "cmd"})],
            needs: Needs::default(),
            budget: Budget {
                attempts: 5,
                max_rework: None,
                max_depth: None,
                max_children: None,
                max_tasks: None,
            },
        };
        let s = serde_json::to_string(&c).unwrap();
        assert!(!s.contains("min_ram_gb"), "None must be omitted: {s}");
        assert!(!s.contains("max_rework"), "None must be omitted: {s}");
        assert!(s.contains("\"attempts\":5"));
    }

    #[test]
    fn task_state_roundtrip() {
        for s in ["pending", "ready", "leased", "review", "done", "blocked"] {
            let st = TaskState::parse(s).expect(s);
            assert_eq!(st.as_str(), s);
        }
        assert!(TaskState::parse("banana").is_none());
    }

    #[test]
    fn verdict_as_str() {
        assert_eq!(Verdict::Approved.as_str(), "approved");
        assert_eq!(Verdict::ChangesRequested.as_str(), "changes_requested");
        assert_eq!(Verdict::Rejected.as_str(), "rejected");
    }
}

//! Альтернативные формулировки интеграционных тестов (из `integration_verified.rs`).
//!
//! Не дублируют `integration.rs` по покрытию, но полезны как независимые
//! формулировки тех же сценариев. Запуск:
//!
//!   TEST_DATABASE_URL=postgres://... \
//!     cargo test -p swarm-core --test integration_alt -- --ignored --test-threads=1

use swarm_core::{Budget, DispatcherError, Needs, SwarmDispatcher, TaskContract, Verdict};
use uuid::Uuid;

fn dsn() -> Option<String> {
    std::env::var("TEST_DATABASE_URL").ok()
}

fn raw(dsn: &str) -> postgres::Client {
    postgres::Client::connect(dsn, postgres::NoTls).unwrap()
}

fn reset(dsn: &str) {
    raw(dsn)
        .batch_execute("truncate events, reviews, task_deps, artifacts, tasks, workers cascade")
        .unwrap();
}

fn contract() -> TaskContract {
    TaskContract {
        kind: "t".into(),
        description: None,
        checks: vec![serde_json::json!({"type":"cmd","run":"true"})],
        needs: Needs::default(),
        budget: Budget::default(),
    }
}

fn worker(d: &mut SwarmDispatcher, id: &str) {
    d.register_worker(id, &serde_json::json!({"ram_gb": 16, "models": {"coder_class": 2}}), &[])
        .unwrap();
}

fn ready_task(d: &mut SwarmDispatcher) -> Uuid {
    let t = Uuid::new_v4();
    d.add_task(t, &contract(), None, 1000, 0).unwrap();
    d.promote_ready().unwrap();
    t
}

#[test]
#[ignore]
fn full_cycle_claim_save_complete_review() {
    let Some(dsn) = dsn() else { return };
    reset(&dsn);
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    worker(&mut d, "w1");
    let t = ready_task(&mut d);
    let lease = d.claim("w1", 60).unwrap().expect("task");
    assert_eq!(lease.task_id, t);
    // Контракт приходит сырым JSON; типизированный разбор — явно.
    assert_eq!(lease.typed_contract().unwrap().kind, "t");
    assert!(d.heartbeat(&lease, 60).unwrap());
    d.save_artifact(&lease, "sha256:aa", "/p", None, None).unwrap();
    assert_eq!(d.complete(&lease, "sha256:aa", 5).unwrap(), "review");
    let checks = serde_json::json!([{"type":"cmd","status":"pass","exit_code":0}]);
    assert_eq!(
        d.submit_review(t, "sha256:aa", "rev", Verdict::Approved, &checks).unwrap(),
        "done"
    );
    assert!(d.verify_chain(t).unwrap());
}

#[test]
#[ignore]
fn sqlstate_mapping() {
    let Some(dsn) = dsn() else { return };
    reset(&dsn);
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    worker(&mut d, "w1");
    let a = ready_task(&mut d);
    // WorkerUnknown
    assert!(matches!(d.claim("ghost", 60), Err(DispatcherError::WorkerUnknown)));
    // ContractInvalid (локально)
    let mut bad = contract();
    bad.checks.clear();
    assert!(matches!(
        d.add_task(Uuid::new_v4(), &bad, None, 10, 0),
        Err(DispatcherError::ContractInvalid)
    ));
    // Cycle / TaskNotFound
    let b = Uuid::new_v4();
    d.add_task(b, &contract(), Some(a), 1000, 0).unwrap();
    d.add_dep(b, a).unwrap();
    assert!(matches!(
        d.add_dep(a, b),
        Err(DispatcherError::TaskNotPending) | Err(DispatcherError::CycleDetected)
    ));
    assert!(matches!(d.add_dep(b, Uuid::new_v4()), Err(DispatcherError::TaskNotFound)));
    // LeaseLost + SelfReview + ReviewStale
    let lease = d.claim("w1", 60).unwrap().unwrap();
    d.save_artifact(&lease, "sha256:aa", "/p", None, None).unwrap();
    d.complete(&lease, "sha256:aa", 1).unwrap();
    assert!(matches!(d.complete(&lease, "sha256:aa", 1), Err(DispatcherError::LeaseLost)));
    let ok = serde_json::json!([{"type":"cmd","status":"pass"}]);
    assert!(matches!(
        d.submit_review(a, "sha256:aa", "w1", Verdict::Approved, &ok),
        Err(DispatcherError::SelfReview)
    ));
    assert!(matches!(
        d.submit_review(a, "sha256:zz", "rev", Verdict::Approved, &ok),
        Err(DispatcherError::ReviewStale)
    ));
    assert!(matches!(
        d.submit_review(a, "sha256:aa", "rev", Verdict::Approved, &serde_json::json!([{"status":"fail"}])),
        Err(DispatcherError::ChecksFailed)
    ));
}

#[test]
#[ignore]
fn zombie_is_fenced_and_heartbeat_false() {
    let Some(dsn) = dsn() else { return };
    reset(&dsn);
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    worker(&mut d, "w1");
    let t = ready_task(&mut d);
    let old = d.claim("w1", 60).unwrap().unwrap();
    raw(&dsn)
        .execute("update tasks set lease_until = now() - interval '1 second' where id=$1", &[&t])
        .unwrap();
    assert!(!d.heartbeat(&old, 60).unwrap());
    assert_eq!(d.reclaim_expired().unwrap(), 1);
    let new = d.claim("w1", 60).unwrap().unwrap();
    assert!(new.epoch > old.epoch);
    assert!(matches!(
        d.save_artifact(&old, "sha256:x", "/p", None, None),
        Err(DispatcherError::LeaseLost)
    ));
    assert!(d.heartbeat(&new, 60).unwrap());
}

//! Integration-тесты против реального Postgres.
//!
//! Запуск:
//!   TEST_DATABASE_URL=postgres://swarm:pw@localhost:5432/swarm \
//!     cargo test -p swarm-core --test integration -- --ignored --test-threads=1
//!
//! Без `TEST_DATABASE_URL` тесты пропускаются.

use swarm_core::{
    Budget, DispatcherError, Needs, SwarmDispatcher, TaskContract, Verdict,
};
use uuid::Uuid;

fn dsn() -> Option<String> {
    std::env::var("TEST_DATABASE_URL").ok()
}

fn truncate(d: &mut SwarmDispatcher) {
    // Прямой SQL: fixture-очистка. Не через методы, чтобы не зависеть от кода.
    let mut client = postgres::Client::connect(
        &std::env::var("TEST_DATABASE_URL").unwrap(),
        postgres::NoTls,
    )
    .unwrap();
    client
        .batch_execute(
            "TRUNCATE events, reviews, task_deps, artifacts, tasks, workers CASCADE",
        )
        .unwrap();
    // Принудительно возвращаем d в чистое состояние.
    *d = SwarmDispatcher::connect(&std::env::var("TEST_DATABASE_URL").unwrap()).unwrap();
}

fn contract(kind: &str) -> TaskContract {
    TaskContract {
        kind: kind.into(),
        description: None,
        checks: vec![serde_json::json!({"type": "cmd", "run": "true"})],
        needs: Needs::default(),
        budget: Budget::default(),
    }
}

#[test]
#[ignore]
fn add_task_and_list() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);

    let id = Uuid::new_v4();
    d.add_task(id, &contract("test"), None, 1000, 5).unwrap();

    let rows = d.list_tasks(None, 10).unwrap();
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0].id, id);
    assert_eq!(rows[0].state, "pending");
    assert_eq!(rows[0].priority, 5);
}

#[test]
#[ignore]
fn add_dep_cycle_rejected() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);

    let a = Uuid::new_v4();
    let b = Uuid::new_v4();
    d.add_task(a, &contract("a"), None, 1000, 0).unwrap();
    d.add_task(b, &contract("b"), Some(a), 1000, 0).unwrap();

    d.add_dep(b, a).unwrap();
    let err = d.add_dep(a, b).unwrap_err();
    assert!(matches!(err, DispatcherError::CycleDetected), "got: {err:?}");
}

#[test]
#[ignore]
fn claim_and_fencing() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);

    d.register_worker(
        "w1",
        &serde_json::json!({"ram_gb": 16, "models": {"coder_class": 2}}),
        &[],
    )
    .unwrap();

    let id = Uuid::new_v4();
    d.add_task(id, &contract("t"), None, 1000, 0).unwrap();
    d.promote_ready().unwrap();

    let lease = d.claim("w1", 300).unwrap().expect("lease");
    assert_eq!(lease.task_id, id);
    assert_eq!(lease.epoch, 1);

    // Вторая попытка claim — пусто (задача занята).
    assert!(d.claim("w1", 300).unwrap().is_none());

    // Артефакт с правильным epoch — ок.
    d.save_artifact(&lease, "sha256:aaa", "/tmp/a", None, None)
        .unwrap();

    // Артефакт с чужим epoch — LeaseLost.
    let mut stale = lease.clone();
    stale.epoch = 0;
    let err = d
        .save_artifact(&stale, "sha256:bbb", "/tmp/b", None, None)
        .unwrap_err();
    assert!(matches!(err, DispatcherError::LeaseLost));
}

#[test]
#[ignore]
fn complete_and_review_self_rejected() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);

    d.register_worker("w1", &serde_json::json!({"ram_gb": 16}), &[])
        .unwrap();
    let id = Uuid::new_v4();
    d.add_task(id, &contract("t"), None, 1000, 0).unwrap();
    d.promote_ready().unwrap();
    let lease = d.claim("w1", 300).unwrap().unwrap();
    d.save_artifact(&lease, "sha256:x", "/tmp/x", None, None)
        .unwrap();
    let state = d.complete(&lease, "sha256:x", 10).unwrap();
    assert_eq!(state, "review");

    // Рецензент = автор → SelfReview.
    let checks = serde_json::json!([{"type": "cmd", "status": "pass"}]);
    let err = d
        .submit_review(id, "sha256:x", "w1", Verdict::Approved, &checks)
        .unwrap_err();
    assert!(matches!(err, DispatcherError::SelfReview));

    // Другой рецензент → done.
    let state = d
        .submit_review(id, "sha256:x", "reviewer", Verdict::Approved, &checks)
        .unwrap();
    assert_eq!(state, "done");
}

#[test]
#[ignore]
fn verify_chain_after_operations() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);

    d.register_worker("w1", &serde_json::json!({"ram_gb": 16}), &[])
        .unwrap();
    let id = Uuid::new_v4();
    d.add_task(id, &contract("t"), None, 1000, 0).unwrap();
    d.promote_ready().unwrap();
    let lease = d.claim("w1", 300).unwrap().unwrap();
    d.save_artifact(&lease, "sha256:x", "/tmp/x", None, None)
        .unwrap();
    d.complete(&lease, "sha256:x", 10).unwrap();

    assert!(d.verify_chain(id).unwrap());
}

// ============================================================
// Новые тесты step 1 v0.2 (см. docs/TZ_v0.2_step1_fixes.md, §8.1)
// ============================================================

fn raw(dsn: &str) -> postgres::Client {
    postgres::Client::connect(dsn, postgres::NoTls).unwrap()
}

fn count(dsn: &str, ids: &[Uuid]) -> i64 {
    raw(dsn)
        .query_one("select count(*) from tasks where id = any($1)", &[&ids.to_vec()])
        .unwrap()
        .get(0)
}

/// Контракт, который SQL принимает (kind не обязателен, число может быть
/// дробным), но который Rust не может десериализовать ПОСЛЕ того, как аренда
/// уже выдана. Регрессия на баг из `types.rs`: `Lease.contract` — сырой JSON,
/// разбор — только явно через `typed_contract()`.
#[test]
#[ignore]
fn contract_accepted_by_sql_but_not_by_rust_must_not_strand_the_task() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);
    d.register_worker("w1", &serde_json::json!({"ram_gb": 16}), &[])
        .unwrap();

    let t = Uuid::new_v4();
    raw(&dsn)
        .execute(
            "select add_task($1, null, $2::jsonb, 100, 0)",
            &[
                &t,
                &serde_json::json!({"checks":[{"a":1}], "budget":{"attempts": 2.5}}),
            ],
        )
        .unwrap();
    d.promote_ready().unwrap();
    let r = d.claim("w1", 3600);
    let state: String = raw(&dsn)
        .query_one("select state from tasks where id=$1", &[&t])
        .unwrap()
        .get(0);
    assert!(
        r.is_ok(),
        "claim failed after lease was already granted -> task stuck in '{state}'"
    );
}

/// Параллельные claim не должны выдать одну задачу дважды.
#[test]
#[ignore]
fn concurrent_claims_are_disjoint() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);
    for i in 0..8 {
        d.register_worker(&format!("w{i}"), &serde_json::json!({"ram_gb": 16}), &[])
            .unwrap();
    }
    for _ in 0..24 {
        d.add_task(Uuid::new_v4(), &contract("t"), None, 1000, 0)
            .unwrap();
    }
    d.promote_ready().unwrap();

    let got = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let hs: Vec<_> = (0..8)
        .map(|i| {
            let got = got.clone();
            let dsn = dsn.clone();
            std::thread::spawn(move || {
                let mut d = SwarmDispatcher::connect(&dsn).unwrap();
                while let Some(l) = d.claim(&format!("w{i}"), 60).unwrap() {
                    got.lock().unwrap().push(l.task_id);
                }
            })
        })
        .collect();
    for h in hs {
        h.join().unwrap();
    }
    let mut v = got.lock().unwrap().clone();
    assert_eq!(v.len(), 24);
    v.sort();
    v.dedup();
    assert_eq!(v.len(), 24);
}

/// Локальная ошибка в замыкании -> rollback. Именно этот тест ловит мутацию
/// «коммитить даже при ошибке» (M2): путь идёт через код обёртки, а не Postgres.
#[test]
#[ignore]
fn with_transaction_rolls_back_on_error() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);
    let (a, b) = (Uuid::new_v4(), Uuid::new_v4());
    let r = d.with_transaction(|tx| {
        tx.add_task(a, &contract("t"), None, 100, 0)?;
        assert_eq!(
            count(&dsn, &[a]),
            0,
            "uncommitted insert must be invisible to other connections"
        );
        let mut bad = contract("t");
        bad.checks.clear();
        tx.add_task(b, &bad, None, 100, 0)?; // локальная валидация -> Err
        Ok(())
    });
    assert!(matches!(r, Err(DispatcherError::ContractInvalid)));
    assert_eq!(count(&dsn, &[a, b]), 0);
}

/// SQL-ошибка посреди графа -> откат всех трёх вставок (частичного графа нет).
#[test]
#[ignore]
fn with_transaction_rolls_back_on_sql_error_midway() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);
    let (a, b) = (Uuid::new_v4(), Uuid::new_v4());
    let r = d.with_transaction(|tx| {
        tx.add_task(a, &contract("t"), None, 100, 0)?;
        tx.add_task(b, &contract("t"), Some(a), 100, 0)?;
        tx.add_dep(b, a)?;
        tx.add_dep(a, b)?; // цикл (SQL GR001/GR008) -> откат всех трёх
        Ok(())
    });
    assert!(r.is_err());
    assert_eq!(count(&dsn, &[a, b]), 0);
}

/// Успешный граф коммитится целиком и атомарно.
#[test]
#[ignore]
fn with_transaction_commits_whole_graph_atomically() {
    let Some(dsn) = dsn() else { return };
    let mut d = SwarmDispatcher::connect(&dsn).unwrap();
    truncate(&mut d);
    let ids: Vec<Uuid> = (0..4).map(|_| Uuid::new_v4()).collect();
    let n = d
        .with_transaction(|tx| {
            tx.add_task(ids[0], &contract("t"), None, 100, 0)?;
            for w in ids.windows(2) {
                tx.add_task(w[1], &contract("t"), Some(ids[0]), 100, 0)?;
                tx.add_dep(w[1], w[0])?;
            }
            tx.promote_ready()
        })
        .unwrap();
    assert_eq!(n, 1); // готов только корень
    assert_eq!(count(&dsn, &ids), 4);
}

use postgres::{Client, NoTls};
use serde_json::json;
use std::sync::{Arc, Mutex};
use swarm_core::*;
use uuid::Uuid;

/// DSN из окружения. Приложение v0.3 (ТЗ §0): убран жёстко зашитый порт 5432 —
/// тесты ходят туда, куда указывает TEST_DATABASE_URL (у нас 127.0.0.1:55440).
fn dsn() -> String {
    std::env::var("TEST_DATABASE_URL").unwrap_or_else(|_| {
        "host=localhost port=5432 user=postgres password=pw dbname=v0test".to_string()
    })
}

fn raw() -> Client { Client::connect(&dsn(), NoTls).unwrap() }
fn reset() {
    raw().batch_execute("truncate events, reviews, task_deps, artifacts, tasks, workers cascade").unwrap();
}
fn d() -> SwarmDispatcher { SwarmDispatcher::connect(&dsn()).unwrap() }
fn contract() -> TaskContract {
    TaskContract { kind: "t".into(), description: None, checks: vec![json!({"type":"cmd","run":"true"})],
                   needs: Needs::default(), budget: Budget::default() }
}
fn worker(d: &mut SwarmDispatcher, id: &str) {
    d.register_worker(id, &json!({"ram_gb": 16, "models": {"coder_class": 2}}), &[]).unwrap();
}
fn ready_task(d: &mut SwarmDispatcher) -> Uuid {
    let t = Uuid::new_v4();
    d.add_task(t, &contract(), None, 1000, 0).unwrap();
    d.promote_ready().unwrap();
    t
}

#[test]
fn full_cycle_claim_save_complete_review() {
    reset();
    let mut d = d();
    worker(&mut d, "w1");
    let t = ready_task(&mut d);
    let lease = d.claim("w1", 60).unwrap().expect("task");
    assert_eq!(lease.task_id, t);
    assert!(d.heartbeat(&lease, 60).unwrap());
    d.save_artifact(&lease, "sha256:aa", "/p", None, None).unwrap();
    assert_eq!(d.complete(&lease, "sha256:aa", 5).unwrap(), "review");
    let checks = json!([{"type":"cmd","status":"pass","exit_code":0}]);
    assert_eq!(d.submit_review(t, "sha256:aa", "rev", Verdict::Approved, &checks).unwrap(), "done");
    assert!(d.verify_chain(t).unwrap());
}

#[test]
fn sqlstate_mapping() {
    reset();
    let mut d = d();
    worker(&mut d, "w1");
    let a = ready_task(&mut d);
    // WorkerUnknown
    assert!(matches!(d.claim("ghost", 60), Err(DispatcherError::WorkerUnknown)));
    // ContractInvalid (локально) 
    let mut bad = contract(); bad.checks.clear();
    assert!(matches!(d.add_task(Uuid::new_v4(), &bad, None, 10, 0), Err(DispatcherError::ContractInvalid)));
    // Cycle / TaskNotFound
    let b = Uuid::new_v4();
    d.add_task(b, &contract(), Some(a), 1000, 0).unwrap();
    d.add_dep(b, a).unwrap();
    assert!(matches!(d.add_dep(a, b), Err(DispatcherError::TaskNotPending) | Err(DispatcherError::CycleDetected)));
    assert!(matches!(d.add_dep(b, Uuid::new_v4()), Err(DispatcherError::TaskNotFound)));
    // LeaseLost + SelfReview + ReviewStale
    let lease = d.claim("w1", 60).unwrap().unwrap();
    d.save_artifact(&lease, "sha256:aa", "/p", None, None).unwrap();
    d.complete(&lease, "sha256:aa", 1).unwrap();
    assert!(matches!(d.complete(&lease, "sha256:aa", 1), Err(DispatcherError::LeaseLost)));
    let ok = json!([{"type":"cmd","status":"pass"}]);
    assert!(matches!(d.submit_review(a, "sha256:aa", "w1", Verdict::Approved, &ok), Err(DispatcherError::SelfReview)));
    assert!(matches!(d.submit_review(a, "sha256:zz", "rev", Verdict::Approved, &ok), Err(DispatcherError::ReviewStale)));
    assert!(matches!(d.submit_review(a, "sha256:aa", "rev", Verdict::Approved, &json!([{"status":"fail"}])),
                     Err(DispatcherError::ChecksFailed)));
}

#[test]
fn zombie_is_fenced_and_heartbeat_false() {
    reset();
    let mut d = d();
    worker(&mut d, "w1");
    let t = ready_task(&mut d);
    let old = d.claim("w1", 60).unwrap().unwrap();
    raw().execute("update tasks set lease_until = now() - interval '1 second' where id=$1", &[&t]).unwrap();
    assert!(!d.heartbeat(&old, 60).unwrap());
    assert_eq!(d.reclaim_expired().unwrap(), 1);
    let new = d.claim("w1", 60).unwrap().unwrap();
    assert!(new.epoch > old.epoch);
    assert!(matches!(d.save_artifact(&old, "sha256:x", "/p", None, None), Err(DispatcherError::LeaseLost)));
    assert!(d.heartbeat(&new, 60).unwrap());
}

#[test]
fn concurrent_claims_are_disjoint() {
    reset();
    let mut setup = d();
    for i in 0..8 { worker(&mut setup, &format!("w{i}")); }
    for _ in 0..24 { setup.add_task(Uuid::new_v4(), &contract(), None, 1000, 0).unwrap(); }
    setup.promote_ready().unwrap();
    let got = Arc::new(Mutex::new(Vec::new()));
    let hs: Vec<_> = (0..8).map(|i| {
        let got = got.clone();
        std::thread::spawn(move || {
            let mut d = d();
            while let Some(l) = d.claim(&format!("w{i}"), 60).unwrap() { got.lock().unwrap().push(l.task_id); }
        })
    }).collect();
    for h in hs { h.join().unwrap(); }
    let mut v = got.lock().unwrap().clone();
    assert_eq!(v.len(), 24);
    v.sort(); v.dedup();
    assert_eq!(v.len(), 24);
}

/// Контракт, который SQL принимает (kind не обязателен, число может быть дробным),
/// но который Rust не может десериализовать ПОСЛЕ того, как аренда уже выдана.
#[test]
fn contract_accepted_by_sql_but_not_by_rust_must_not_strand_the_task() {
    reset();
    let mut d = d();
    worker(&mut d, "w1");
    let t = Uuid::new_v4();
    raw().execute("select add_task($1, null, $2::jsonb, 100, 0)",
                  &[&t, &json!({"checks":[{"a":1}], "budget":{"attempts": 2.5}})]).unwrap();
    d.promote_ready().unwrap();
    let r = d.claim("w1", 3600);
    let state: String = raw().query_one("select state from tasks where id=$1", &[&t]).unwrap().get(0);
    eprintln!("claim result: {:?}; task state afterwards: {state}", r.as_ref().map(|_| "lease").map_err(|e| e.to_string()));
    assert!(r.is_ok(), "claim failed after lease was already granted -> task stuck in '{state}' for an hour");
}

fn count(ids: &[Uuid]) -> i64 {
    raw().query_one("select count(*) from tasks where id = any($1)", &[&ids.to_vec()]).unwrap().get(0)
}

#[test]
fn with_transaction_rolls_back_on_error() {
    reset();
    let mut d = d();
    let (a, b) = (Uuid::new_v4(), Uuid::new_v4());
    let r = d.with_transaction(|tx| {
        tx.add_task(a, &contract(), None, 100, 0)?;
        assert_eq!(count(&[a]), 0, "uncommitted insert must be invisible to other connections");
        let mut bad = contract(); bad.checks.clear();
        tx.add_task(b, &bad, None, 100, 0)?;          // локальная валидация -> Err
        Ok(())
    });
    assert!(matches!(r, Err(DispatcherError::ContractInvalid)));
    assert_eq!(count(&[a, b]), 0);
}

#[test]
fn with_transaction_rolls_back_on_sql_error_midway() {
    reset();
    let mut d = d();
    let (a, b) = (Uuid::new_v4(), Uuid::new_v4());
    let r = d.with_transaction(|tx| {
        tx.add_task(a, &contract(), None, 100, 0)?;
        tx.add_task(b, &contract(), Some(a), 100, 0)?;
        tx.add_dep(b, a)?;
        tx.add_dep(a, b)?;                              // цикл (SQL GR001 или GR008) -> откат всех трёх
        Ok(())
    });
    assert!(r.is_err());
    assert_eq!(count(&[a, b]), 0);
}

#[test]
fn with_transaction_commits_whole_graph_atomically() {
    reset();
    let mut d = d();
    let ids: Vec<Uuid> = (0..4).map(|_| Uuid::new_v4()).collect();
    let n = d.with_transaction(|tx| {
        tx.add_task(ids[0], &contract(), None, 100, 0)?;
        for w in ids.windows(2) {
            tx.add_task(w[1], &contract(), Some(ids[0]), 100, 0)?;
            tx.add_dep(w[1], w[0])?;
        }
        tx.promote_ready()
    }).unwrap();
    assert_eq!(n, 1);                                   // готов только корень
    assert_eq!(count(&ids), 4);
}

[package]
name = "swarm-llm"
version.workspace = true
edition.workspace = true
description = "Общий LLM-клиент (sync): openai / anthropic / openai-compatible / mock"

[dependencies]
reqwest = { version = "0.12", features = ["json", "blocking", "rustls-tls"] }
serde = { workspace = true }
serde_json = { workspace = true }
thiserror = { workspace = true }

//! Ошибки LLM-клиента.

use thiserror::Error;

#[derive(Debug, Error)]
pub enum LlmError {
    #[error("llm config error: {0}")]
    Config(String),

    #[error("llm transport error: {0}")]
    Transport(String),

    #[error("llm http error: status={status} body={body}")]
    Http { status: u16, body: String },

    #[error("llm response is not valid json: {0}")]
    InvalidJson(String),

    #[error("llm request timed out")]
    Timeout,
}

impl LlmError {
    /// Транзиентная ошибка — имеет смысл повторить (сеть, 5xx, 429, таймаут).
    pub fn is_transient(&self) -> bool {
        match self {
            LlmError::Timeout => true,
            LlmError::Transport(_) => true,
            LlmError::Http { status, .. } => *status >= 500 || *status == 429,
            _ => false,
        }
    }

    /// HTTP-статус, если ошибка HTTP.
    pub fn status(&self) -> Option<u16> {
        match self {
            LlmError::Http { status, .. } => Some(*status),
            _ => None,
        }
    }
}

pub type Result<T> = std::result::Result<T, LlmError>;

//! Общий LLM-клиент (sync, `reqwest::blocking`).
//!
//! Провайдеры: `openai`, `anthropic`, `openai-compatible` (алиас `relayfast`),
//! `mock` (ответ из файла — для тестов).
//!
//! Вынесен из `swarm-planner` в отдельный crate (ТЗ v0.3 §2), чтобы Planner и
//! LLM-worker использовали один и тот же клиент без дублирования.

use serde::{Deserialize, Serialize};

pub mod error;

pub use error::LlmError;

/// Конфигурация LLM, читается из env.
#[derive(Debug, Clone)]
pub struct LlmConfig {
    pub provider: String,
    pub api_key: Option<String>,
    pub model: String,
    pub base_url: Option<String>,
    pub max_retries: u32,
    pub max_tokens: u32,
    pub mock_file: Option<String>,
    /// Таймаут одного HTTP-запроса, секунды.
    pub timeout_sec: u64,
}

impl LlmConfig {
    /// Читает конфигурацию из env с заданным префиксом (по умолчанию `LLM_`).
    ///
    /// Для обратной совместимости с Planner поддерживается префикс `PLANNER_LLM_`.
    pub fn from_env_prefixed(prefix: &str) -> Result<Self, LlmError> {
        let var = |name: &str| std::env::var(format!("{prefix}{name}"));
        // Обратная совместимость: PLANNER_LLM_* (если prefix == "PLANNER_").
        let legacy = |name: &str| std::env::var(format!("PLANNER_LLM_{name}"));

        let provider = var("PROVIDER")
            .or_else(|_| legacy("PROVIDER"))
            .map_err(|_| LlmError::Config(format!("{prefix}PROVIDER required")))?;
        let api_key = var("API_KEY").or_else(|_| legacy("API_KEY")).ok();
        if provider != "mock" && provider != "openai-compatible" && api_key.is_none() {
            return Err(LlmError::Config(
                "API key required for this provider".into(),
            ));
        }
        let model = var("MODEL").or_else(|_| legacy("MODEL")).unwrap_or_else(|_| "mock".into());
        let base_url = var("BASE_URL").or_else(|_| legacy("BASE_URL")).ok();
        if provider == "openai-compatible" && base_url.is_none() {
            return Err(LlmError::Config(
                "BASE_URL required for openai-compatible".into(),
            ));
        }
        let max_retries = var("MAX_RETRIES")
            .or_else(|_| std::env::var("PLANNER_MAX_RETRIES"))
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(2);
        let max_tokens = var("MAX_TOKENS")
            .or_else(|_| std::env::var("PLANNER_BUDGET_TOKENS"))
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(4096);
        let mock_file = var("MOCK_RESPONSE_FILE")
            .or_else(|_| legacy("MOCK_RESPONSE_FILE"))
            .ok();
        let timeout_sec = var("TIMEOUT_SEC")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(120);
        Ok(Self {
            provider,
            api_key,
            model,
            base_url,
            max_retries,
            max_tokens,
            mock_file,
            timeout_sec,
        })
    }

    /// Совместимость: читает `LLM_*`, при отсутствии — `PLANNER_LLM_*`.
    pub fn from_env() -> Result<Self, LlmError> {
        Self::from_env_prefixed("LLM_")
    }
}

/// Запрос к LLM.
#[derive(Debug, Clone)]
pub struct LlmRequest {
    pub system: String,
    pub user: String,
    pub max_tokens: Option<u32>,
    pub temperature: Option<f32>,
}

/// Ответ LLM.
#[derive(Debug, Clone)]
pub struct LlmResponse {
    pub text: String,
    pub tokens_in: u32,
    pub tokens_out: u32,
    pub model: String,
}

/// Трейт клиента — позволяет подменять реализацию в тестах.
pub trait LlmClient: Send + Sync {
    fn complete(&self, req: &LlmRequest) -> Result<LlmResponse, LlmError>;
}

/// HTTP-клиент (blocking).
pub struct HttpLlmClient {
    cfg: LlmConfig,
    http: reqwest::blocking::Client,
}

#[derive(Serialize)]
struct ChatMessage<'a> {
    role: &'a str,
    content: &'a str,
}

#[derive(Serialize)]
struct OpenAiRequest<'a> {
    model: &'a str,
    messages: Vec<ChatMessage<'a>>,
    max_tokens: u32,
    temperature: f32,
}

#[derive(Deserialize)]
struct OpenAiChoice {
    message: OpenAiMessage,
}
#[derive(Deserialize)]
struct OpenAiMessage {
    content: String,
}
#[derive(Deserialize)]
struct OpenAiUsage {
    #[serde(default)]
    prompt_tokens: u32,
    #[serde(default)]
    completion_tokens: u32,
}
#[derive(Deserialize)]
struct OpenAiResponse {
    choices: Vec<OpenAiChoice>,
    #[serde(default)]
    usage: Option<OpenAiUsage>,
    #[serde(default)]
    model: Option<String>,
}

#[derive(Serialize)]
struct AnthropicRequest<'a> {
    model: &'a str,
    max_tokens: u32,
    system: &'a str,
    messages: Vec<ChatMessage<'a>>,
}
#[derive(Deserialize)]
struct AnthropicContent {
    text: String,
}
#[derive(Deserialize)]
struct AnthropicUsage {
    #[serde(default)]
    input_tokens: u32,
    #[serde(default)]
    output_tokens: u32,
}
#[derive(Deserialize)]
struct AnthropicResponse {
    content: Vec<AnthropicContent>,
    #[serde(default)]
    usage: Option<AnthropicUsage>,
    #[serde(default)]
    model: Option<String>,
}

impl HttpLlmClient {
    pub fn new(cfg: LlmConfig) -> Result<Self, LlmError> {
        let http = reqwest::blocking::Client::builder()
            .timeout(std::time::Duration::from_secs(cfg.timeout_sec))
            .build()
            .map_err(|e| LlmError::Transport(e.to_string()))?;
        Ok(Self { cfg, http })
    }

    pub fn config(&self) -> &LlmConfig {
        &self.cfg
    }

    fn dispatch(&self, req: &LlmRequest) -> Result<LlmResponse, LlmError> {
        let max_tokens = req.max_tokens.unwrap_or(self.cfg.max_tokens);
        match self.cfg.provider.as_str() {
            "mock" => self.mock_response(),
            "openai" => self.openai_chat(req, max_tokens, self.cfg.base_url.as_deref().unwrap_or("https://api.openai.com")),
            "openai-compatible" | "relayfast" => {
                let base = self
                    .cfg
                    .base_url
                    .as_deref()
                    .ok_or_else(|| LlmError::Config("base_url required".into()))?;
                self.openai_chat(req, max_tokens, base)
            }
            "anthropic" => self.anthropic_chat(req, max_tokens),
            other => Err(LlmError::Config(format!("unknown provider: {other}"))),
        }
    }

    fn mock_response(&self) -> Result<LlmResponse, LlmError> {
        let path = self
            .cfg
            .mock_file
            .as_deref()
            .ok_or_else(|| LlmError::Config("mock requires MOCK_RESPONSE_FILE".into()))?;
        let text = std::fs::read_to_string(path)
            .map_err(|e| LlmError::Transport(format!("mock file {path}: {e}")))?;
        Ok(LlmResponse {
            text,
            tokens_in: 0,
            tokens_out: 0,
            model: "mock".into(),
        })
    }

    fn openai_chat(&self, req: &LlmRequest, max_tokens: u32, base: &str) -> Result<LlmResponse, LlmError> {
        let url = format!("{}/v1/chat/completions", base.trim_end_matches('/'));
        let body = OpenAiRequest {
            model: &self.cfg.model,
            messages: vec![
                ChatMessage { role: "system", content: &req.system },
                ChatMessage { role: "user", content: &req.user },
            ],
            max_tokens,
            temperature: req.temperature.unwrap_or(0.2),
        };
        let mut r = self.http.post(&url).json(&body);
        if let Some(k) = &self.cfg.api_key {
            r = r.bearer_auth(k);
        }
        let resp = r.send().map_err(|e| LlmError::Transport(e.to_string()))?;
        let status = resp.status();
        let text = resp.text().map_err(|e| LlmError::Transport(e.to_string()))?;
        if !status.is_success() {
            return Err(LlmError::Http {
                status: status.as_u16(),
                body: truncate(&text, 400),
            });
        }
        let parsed: OpenAiResponse = serde_json::from_str(&text)
            .map_err(|e| LlmError::InvalidJson(format!("{e}: {}", truncate(&text, 400))))?;
        let usage = parsed.usage.unwrap_or(OpenAiUsage { prompt_tokens: 0, completion_tokens: 0 });
        parsed
            .choices
            .into_iter()
            .next()
            .map(|c| LlmResponse {
                text: c.message.content,
                tokens_in: usage.prompt_tokens,
                tokens_out: usage.completion_tokens,
                model: parsed.model.unwrap_or_else(|| self.cfg.model.clone()),
            })
            .ok_or_else(|| LlmError::InvalidJson("empty choices".into()))
    }

    fn anthropic_chat(&self, req: &LlmRequest, max_tokens: u32) -> Result<LlmResponse, LlmError> {
        let base = self.cfg.base_url.as_deref().unwrap_or("https://api.anthropic.com");
        let url = format!("{}/v1/messages", base.trim_end_matches('/'));
        let body = AnthropicRequest {
            model: &self.cfg.model,
            max_tokens,
            system: &req.system,
            messages: vec![ChatMessage { role: "user", content: &req.user }],
        };
        let key = self
            .cfg
            .api_key
            .as_deref()
            .ok_or_else(|| LlmError::Config("anthropic requires api key".into()))?;
        let resp = self
            .http
            .post(&url)
            .header("x-api-key", key)
            .header("anthropic-version", "2023-06-01")
            .json(&body)
            .send()
            .map_err(|e| LlmError::Transport(e.to_string()))?;
        let status = resp.status();
        let text = resp.text().map_err(|e| LlmError::Transport(e.to_string()))?;
        if !status.is_success() {
            return Err(LlmError::Http {
                status: status.as_u16(),
                body: truncate(&text, 400),
            });
        }
        let parsed: AnthropicResponse = serde_json::from_str(&text)
            .map_err(|e| LlmError::InvalidJson(format!("{e}: {}", truncate(&text, 400))))?;
        let usage = parsed.usage.unwrap_or(AnthropicUsage { input_tokens: 0, output_tokens: 0 });
        parsed
            .content
            .into_iter()
            .next()
            .map(|c| LlmResponse {
                text: c.text,
                tokens_in: usage.input_tokens,
                tokens_out: usage.output_tokens,
                model: parsed.model.unwrap_or_else(|| self.cfg.model.clone()),
            })
            .ok_or_else(|| LlmError::InvalidJson("empty content".into()))
    }
}

impl LlmClient for HttpLlmClient {
    fn complete(&self, req: &LlmRequest) -> Result<LlmResponse, LlmError> {
        self.dispatch(req)
    }
}

/// Фабрика из env.
pub fn from_env() -> Result<Box<dyn LlmClient>, LlmError> {
    let cfg = LlmConfig::from_env()?;
    Ok(Box::new(HttpLlmClient::new(cfg)?))
}

/// Фабрика из env с префиксом.
pub fn from_env_prefixed(prefix: &str) -> Result<Box<dyn LlmClient>, LlmError> {
    let cfg = LlmConfig::from_env_prefixed(prefix)?;
    Ok(Box::new(HttpLlmClient::new(cfg)?))
}

fn truncate(s: &str, n: usize) -> String {
    if s.len() <= n {
        s.to_string()
    } else {
        format!("{}…", &s[..n.min(s.len())])
    }
}

